package com.example.puller.service;import com.example.puller.entity.OutboxEvent;import com.example.puller.repository.OutboxRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.data.domain.PageRequest;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class OutboxClaimService{private final OutboxRepository repo;private final int batch;private final int maxRetries;public OutboxClaimService(OutboxRepository r,@Value("${order.poller.batch-size:50}")int b,@Value("${order.poller.max-retries:5}")int m){repo=r;batch=b;maxRetries=m;}@Transactional public List<OutboxEvent> claim(){List<OutboxEvent> list=repo.findNewForUpdate(PageRequest.of(0,batch));Date now=new Date();for(OutboxEvent e:list){e.setStatus("PROCESSING");e.setLockedAt(now);}return repo.saveAll(list);}@Transactional public void published(Long id){OutboxEvent e=repo.findById(id).orElseThrow(()->new IllegalStateException("Outbox not found"));e.setStatus("PUBLISHED");e.setPublishedAt(new Date());e.setLockedAt(null);}@Transactional public void failed(Long id){OutboxEvent e=repo.findById(id).orElseThrow(()->new IllegalStateException("Outbox not found"));int n=e.getRetryCount()+1;e.setRetryCount(n);e.setStatus(n>=maxRetries?"FAILED":"NEW");e.setLockedAt(null);}@Transactional public void recoverStale(){Date cutoff=new Date(System.currentTimeMillis()-300000L);for(OutboxEvent e:repo.findByStatusAndLockedAtBefore("PROCESSING",cutoff)){e.setStatus("NEW");e.setLockedAt(null);}}}
